#!/usr/bin/env node
// Regenerates SHA512 hashes and sizes in electron-builder update YML files
// after the Windows installers have been code-signed (which changes their bytes).
//
// Must run from the repo root. Expects release/*.exe to be the signed installers
// and release/*.yml to be the metadata files generated by electron-builder.
'use strict';

const yaml   = require('js-yaml');
const crypto = require('crypto');
const fs     = require('fs');
const path   = require('path');

const releaseDir = path.resolve('release');
const ymlFiles   = fs.readdirSync(releaseDir).filter(f => f.endsWith('.yml'));

if (ymlFiles.length === 0) {
    console.error('No .yml files found in release/ — nothing to do.');
    process.exit(1);
}

for (const ymlFile of ymlFiles) {
    const ymlPath = path.join(releaseDir, ymlFile);
    let doc;
    try {
        doc = yaml.load(fs.readFileSync(ymlPath, 'utf8'));
    } catch {
        continue;
    }
    if (!doc || !doc.files) continue;

    for (const file of doc.files) {
        const exePath = path.join(releaseDir, file.url);
        if (!fs.existsSync(exePath)) {
            console.warn(`  SKIP ${file.url} (not found)`);
            continue;
        }
        const buf       = fs.readFileSync(exePath);
        file.sha512     = crypto.createHash('sha512').update(buf).digest('base64');
        file.size       = buf.length;
        console.log(`  updated ${file.url}  size=${file.size}`);
    }

    // Top-level sha512 mirrors the default (x64) file entry.
    if (doc.path) {
        const mainBuf = fs.readFileSync(path.join(releaseDir, doc.path));
        doc.sha512    = crypto.createHash('sha512').update(mainBuf).digest('base64');
    }

    fs.writeFileSync(ymlPath, yaml.dump(doc, { lineWidth: -1 }));
    console.log(`Regenerated checksums in ${ymlFile}`);
}
